"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"
import { useState } from "react"
import { Menu, X } from "lucide-react"

export function Navbar() {
  const pathname = usePathname()
  const [isMenuOpen, setIsMenuOpen] = useState(false)

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen)
  }

  return (
    <nav className="fixed top-0 w-full z-50 bg-white border-b">
      <div className="container mx-auto px-4">
        <div className="flex h-16 items-center justify-between">
          <Link href="/" className="text-xl font-bold text-blue-600">
            EduOnline
          </Link>
          
          {/* Mobile menu button */}
          <button 
            onClick={toggleMenu}
            className="md:hidden"
          >
            {isMenuOpen ? (
              <X className="h-6 w-6" />
            ) : (
              <Menu className="h-6 w-6" />
            )}
          </button>

          {/* Desktop Navigation */}
          <div className="hidden md:flex items-center space-x-8">
            <Link 
              href="/courses" 
              className={`text-sm font-medium transition-colors hover:text-blue-600 ${
                pathname === "/courses" ? "text-blue-600" : "text-gray-600"
              }`}
            >
              Khóa học
            </Link>
            <Link 
              href="/instructors" 
              className={`text-sm font-medium transition-colors hover:text-blue-600 ${
                pathname === "/instructors" ? "text-blue-600" : "text-gray-600"
              }`}
            >
              Giảng viên
            </Link>
            <Link 
              href="/about" 
              className={`text-sm font-medium transition-colors hover:text-blue-600 ${
                pathname === "/about" ? "text-blue-600" : "text-gray-600"
              }`}
            >
              Giới thiệu
            </Link>
          </div>

          {/* Desktop Auth Buttons */}
          <div className="hidden md:flex items-center space-x-4">
            <Link 
              href="/login"
              className="text-sm font-medium text-gray-600 hover:text-blue-600"
            >
              Đăng nhập
            </Link>
            <Link 
              href="/register"
              className="text-sm font-medium bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors"
            >
              Đăng ký
            </Link>
          </div>
        </div>

        {/* Mobile Navigation */}
        {isMenuOpen && (
          <div className="md:hidden py-4 border-t">
            <div className="flex flex-col space-y-4">
              <Link 
                href="/courses"
                className={`text-sm font-medium transition-colors hover:text-blue-600 ${
                  pathname === "/courses" ? "text-blue-600" : "text-gray-600"
                }`}
                onClick={() => setIsMenuOpen(false)}
              >
                Khóa học
              </Link>
              <Link 
                href="/instructors"
                className={`text-sm font-medium transition-colors hover:text-blue-600 ${
                  pathname === "/instructors" ? "text-blue-600" : "text-gray-600"
                }`}
                onClick={() => setIsMenuOpen(false)}
              >
                Giảng viên
              </Link>
              <Link 
                href="/about"
                className={`text-sm font-medium transition-colors hover:text-blue-600 ${
                  pathname === "/about" ? "text-blue-600" : "text-gray-600"
                }`}
                onClick={() => setIsMenuOpen(false)}
              >
                Giới thiệu
              </Link>
              <div className="pt-4 border-t flex flex-col space-y-4">
                <Link 
                  href="/login"
                  className="text-sm font-medium text-gray-600 hover:text-blue-600"
                  onClick={() => setIsMenuOpen(false)}
                >
                  Đăng nhập
                </Link>
                <Link 
                  href="/register"
                  className="text-sm font-medium bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors text-center"
                  onClick={() => setIsMenuOpen(false)}
                >
                  Đăng ký
                </Link>
              </div>
            </div>
          </div>
        )}
      </div>
    </nav>
  )
}
